package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.parser.Parser;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Node_siblingNodes_TriageGen2Test {

    @Test
    public void testSiblingNodesWithMultipleChildren() {
        // Setup a DOM structure: <div><p></p><span></span><br></br></div>
        String html = "<div><p></p><span></span><br></br></div>";
        Document doc = Parser.htmlParser().parse(html);
        Element div = doc.selectFirst("div");
        Element p = div.selectFirst("p");
        Element span = div.selectFirst("span");
        Element br = div.selectFirst("br");

        // Execute
        List<Node> siblings = p.siblingNodes();

        // Verify
        assertEquals("The list of sibling nodes should contain all children of the parent", 3, siblings.size());
        assertTrue(siblings.contains(p));
        assertTrue(siblings.contains(span));
        assertTrue(siblings.contains(br));
        assertEquals(div, p.parent());
    }

    @Test
    public void testSiblingNodesWithSingleChild() {
        // Setup: <div><p></p></div>
        String html = "<div><p></p></div>";
        Document doc = Parser.htmlParser().parse(html);
        Element div = doc.selectFirst("div");
        Element p = div.selectFirst("p");

        // Execute
        List<Node> siblings = p.siblingNodes();

        // Verify
        assertEquals(1, siblings.size());
        assertEquals(p, siblings.get(0));
    }

    @Test
    public void testSiblingNodesWithNoSiblings() {
        // Setup: <div></div> (No children)
        // Or a node that is the only child.
        String html = "<div><p></p></div>";
        Document doc = Parser.htmlParser().parse(html);
        Element p = doc.selectFirst("p");

        // Remove parent to simulate a detached node or a node with no parent
        p.remove();

        // Execute & Verify
        // If parent() returns null, siblingNodes() will throw NullPointerException 
        // based on the implementation: return parent().childNodes();
        try {
            p.siblingNodes();
            fail("Expected NullPointerException because parent() is null");
        } catch (NullPointerException e) {
            // Success
        }
    }

    @Test
    public void testSiblingNodesEmptyParent() {
        // Setup: <div></div>
        String html = "<div></div>";
        Document doc = Parser.htmlParser().parse(html);
        Element div = doc.selectFirst("div");

        // We need to test the behavior of childNodes() when empty via a node's parent
        // Since siblingNodes calls parent().childNodes(), we test a node that has a parent but no siblings
        // This is logically impossible in a standard tree unless the node itself is the only child.
        // If the parent exists, the node is a sibling of itself in this context.

        // Testing a node that is the only child of a parent
        String html2 = "<div><p></p></div>";
        Document doc2 = Parser.htmlParser().parse(html2);
        Element p = doc2.selectFirst("p");

        List<Node> siblings = p.siblingNodes();
        assertEquals(1, siblings.size());
        assertEquals(p, siblings.get(0));
    }
}
